-- One-tap sign-in from the Telegram bot (Khikar, 17 Oct 2026; lead design, SMS-level trust like
-- T-auth option b). When the bot tells a bound member their next step, the message also carries a
-- link that signs them in and opens the right page.
--  * The link row is created with the message; its token is generated by the sender at send time
--    (only its sha256 is stored: "armed"), valid 10 minutes from then, single use, bound to the
--    member, the chat's binding and its generation. At most 5 links per member per hour.
--  * Opening the link is inert (GET). Continue (with invisible hCaptcha) starts a normal Supabase
--    phone sign-in for that member; the Send-SMS hook does not send this code anywhere: it seals it
--    (AES-GCM, server key) on the request, the server reads it once, checks it like a typed code and
--    verifies it. Staff and clinic accounts are never signed in this way.
--  * Expired, used, revoked-binding or second-browser opens get "this link has expired".
-- Ships dark: NOREON_TELEGRAM_SIGNIN_LINKS_ENABLED.

create table public.telegram_signin_links(
 id uuid primary key default gen_random_uuid(),
 auth_user_id uuid not null references auth.users(id)on delete cascade,
 binding_id uuid not null references public.telegram_auth_bindings(id)on delete cascade,binding_generation bigint not null,
 principal_ref text not null,
 step text not null check(step in('next_profile','next_questionnaire','next_review','replies_off')),
 message_id uuid not null unique references public.telegram_auth_messages(id)on delete cascade,
 token_hash text unique check(token_hash ~ '^[a-f0-9]{64}$'),
 state text not null default 'pending'check(state in('pending','armed','redeeming','used','expired','cancelled')),
 redeem_nonce_hmac text check(redeem_nonce_hmac ~ '^[a-f0-9]{64}$'),request_id uuid references public.auth_code_requests(id)on delete set null,
 created_at timestamptz not null default clock_timestamp(),armed_at timestamptz,expires_at timestamptz,used_at timestamptz,
 check(state in('pending','cancelled')or(token_hash is not null and armed_at is not null and expires_at is not null)),
 check((state='used')=(used_at is not null))
);
-- Cleanup of the outbox, bindings or requests removes or detaches links (a link never outlives its message).
create index telegram_signin_links_request on public.telegram_signin_links(request_id);
create index telegram_signin_links_user on public.telegram_signin_links(auth_user_id,created_at);
alter table public.telegram_signin_links enable row level security;
revoke all on public.telegram_signin_links from public,anon,authenticated,service_role;
alter table public.auth_code_requests add column signin_link_id uuid references public.telegram_signin_links(id)on delete set null,add column code_sealed text check(length(code_sealed)between 1 and 512);
-- A sealed code lives only while its request is being sent or awaits its one read (two minutes).
create function public._auth_code_request_drop_seal()returns trigger language plpgsql set search_path=''as $$
begin
 if new.code_sealed is not null and new.state not in('sending','sent')then new.code_sealed:=null;end if;
 return new;
end$$;
create trigger auth_code_requests_drop_seal before update on public.auth_code_requests for each row execute function public._auth_code_request_drop_seal();

create or replace function public._telegram_bot_next_step(r public.channel_inbox)returns jsonb
language plpgsql security definer set search_path=''as $$
declare addr text:=r.payload->>'chatId';s public.telegram_channel_settings;b public.telegram_auth_bindings;u uuid;step text;tpl text;loc text;act jsonb;ep public.conversation_endpoints;mid uuid;
begin
 if r.principal_ref is null or coalesce(addr,'')!~'^[1-9][0-9]{0,15}$'then return jsonb_build_object('result','no_chat');end if;
 select * into s from public.telegram_channel_settings where singleton;
 select * into b from public.telegram_auth_bindings where principal_ref=r.principal_ref and active and kind='member'
  and account_ref=public._telegram_account_ref(s);
 if found then
  u:=b.auth_user_id;
  if exists(select 1 from public.workspace_staff where user_id=u)then step:='staff_chat';
  elsif not exists(select 1 from public.profiles where id=u and nullif(btrim(display_name),'')is not null and birth_date is not null and biological_sex in('male','female'))
   or not exists(select 1 from public.patient_consents where user_id=u and version='patient-pilot-v1')then step:='next_profile';
  elsif not exists(select 1 from public.patient_assessments where user_id=u and completed_at is not null)then step:='next_questionnaire';
  elsif not exists(select 1 from public.patient_clinical_cases where user_id=u)then step:='next_review';
  elsif r.endpoint_id is not null then
   -- Already linked (the caller may hold the case lock: never relink here, lock order).
   step:=case when public._telegram_member_eligible(u)then 'ready'else 'unavailable'end;
  else
   -- Can message: link this chat now (respects the member's own turn-off).
   act:=public._telegram_replies_auto(u,false);
   if act->>'ok'='true'then
    select * into ep from public.conversation_endpoints where member_id=u and adapter='telegram'and active and principal_ref=r.principal_ref;
    if ep.id is not null then
     if r.kind in('text','media')then return jsonb_build_object('result','linked','endpointId',ep.id,'generation',ep.generation);end if;
     -- /start that links the chat now: the link confirmation already answers (one message, not two).
     if act->>'result'='linked'then return jsonb_build_object('result','linked');end if;
     step:='ready';
    end if;
   end if;
   step:=coalesce(step,case when act->>'code'='turned_off'then 'replies_off'else 'unavailable'end);
  end if;
  loc:=public._telegram_auth_locale(u);
 elsif exists(select 1 from public.telegram_auth_bindings where principal_ref=r.principal_ref and active and kind='staff')then
  step:='staff_chat';loc:='hy';
 else
  step:='signup';loc:='hy';
 end if;
 -- A member who cannot message for another reason gets the generic pointer (sign in in the app).
 tpl:='telegram.'||case when step='unavailable'then 'signup'else step end;
 -- At most one next-step reply per chat per hour, serialized per chat (a leaf lock nothing else takes).
 perform pg_advisory_xact_lock(hashtextextended('telegram-next-step:'||r.principal_ref,0));
 if exists(select 1 from public.telegram_auth_messages where principal_ref=r.principal_ref
   and template_id in('telegram.signup','telegram.staff_chat','telegram.next_profile','telegram.next_questionnaire','telegram.next_review','telegram.replies_off','telegram.ready')
   and created_at>clock_timestamp()-interval '1 hour')then
  perform public._telegram_audit(u,'bot.next_step',jsonb_build_object('step',step,'inboxId',r.id,'rateLimited',true));
  return jsonb_build_object('result',step||'_rate_limited');end if;
 mid:=public._telegram_auth_enqueue(tpl,coalesce(loc,'hy'),addr,r.principal_ref,null,r.id);
 -- A bound member's next step also carries a one-tap sign-in link (armed only when the message is
 -- sent; at most 5 per member per hour; never for a staff or clinic account).
 if mid is not null and u is not null and step in('next_profile','next_questionnaire','next_review','replies_off')
  and not exists(select 1 from public.workspace_staff where user_id=u)and not exists(select 1 from public.clinic_portal_memberships where user_id=u)
  and(select count(*)from public.telegram_signin_links where auth_user_id=u and created_at>clock_timestamp()-interval '1 hour')<5 then
  insert into public.telegram_signin_links(auth_user_id,binding_id,binding_generation,principal_ref,step,message_id)
  values(u,b.id,b.generation,b.principal_ref,step,mid);
 end if;
 perform public._telegram_audit(u,'bot.next_step',jsonb_build_object('step',step,'inboxId',r.id));
 return jsonb_build_object('result',step);
end$$;

create or replace function public.auth_code_request_claim(p_phone text,p_webhook_id text,p_body_hmac text)returns jsonb
language plpgsql security definer set search_path=''as $$
declare r public.auth_code_requests;u uuid;b public.telegram_auth_bindings;pf public.telegram_phone_proofs;
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 if coalesce(p_webhook_id,'')!~'^[A-Za-z0-9_-]{1,128}$'or coalesce(p_body_hmac,'')!~'^[a-f0-9]{64}$'then return jsonb_build_object('ok',false,'code','invalid');end if;
 perform pg_advisory_xact_lock(hashtextextended('tg-auth-code:'||p_phone,0));
 select * into r from public.auth_code_requests where webhook_id=p_webhook_id;
 if found then
  if r.body_hmac<>p_body_hmac then return jsonb_build_object('ok',false,'code','conflict');end if;
  return jsonb_build_object('ok',true,'replay',true,'requestId',r.id,'state',r.state,'address',r.address);
 end if;
 select * into r from public.auth_code_requests where phone=p_phone and state='issuing'and lease_until>clock_timestamp()order by created_at desc limit 1 for update;
 if not found then return jsonb_build_object('ok',false,'code','no_request');end if;
 -- A one-tap sign-in link's request: the code is not sent anywhere; the hook seals it for the
 -- server that opened the request (route 'link').
 if r.signin_link_id is not null then
  if not exists(select 1 from public.telegram_signin_links l where l.id=r.signin_link_id and l.state='redeeming'and l.request_id=r.id and l.expires_at>clock_timestamp())then
   update public.auth_code_requests set state='refused',refusal='link_unavailable',webhook_id=p_webhook_id,body_hmac=p_body_hmac,updated_at=clock_timestamp()where id=r.id;
   return jsonb_build_object('ok',false,'code','link_unavailable','requestId',r.id);end if;
  update public.auth_code_requests set state='sending',webhook_id=p_webhook_id,body_hmac=p_body_hmac,updated_at=clock_timestamp()where id=r.id;
  return jsonb_build_object('ok',true,'replay',false,'requestId',r.id,'route','link');
 end if;
 -- A fresh contact proof made by this same browser wins: it is how a member who lost
 -- their Telegram account signs in with a new one (replacement follows verification, §2).
 select * into pf from public.telegram_phone_proofs where phone=p_phone and nonce_hmac=r.nonce_hmac and consumed_at is null and cancelled_at is null and expires_at>clock_timestamp()
  and not exists(select 1 from public.telegram_auth_bindings x where x.principal_ref=telegram_phone_proofs.principal_ref and x.active and x.phone<>p_phone)order by proven_at desc limit 1;
 if found then
  update public.auth_code_requests set state='sending',webhook_id=p_webhook_id,body_hmac=p_body_hmac,proof_id=pf.id,address=pf.address,updated_at=clock_timestamp()where id=r.id;
  return jsonb_build_object('ok',true,'replay',false,'requestId',r.id,'address',pf.address,'route','proof');
 end if;
 u:=public._auth_user_for_phone(p_phone);
 select * into b from public.telegram_auth_bindings where kind='member'and auth_user_id=u and phone=p_phone and active;
 if not found then
  update public.auth_code_requests set state='refused',refusal='no_destination',webhook_id=p_webhook_id,body_hmac=p_body_hmac,updated_at=clock_timestamp()where id=r.id;
  return jsonb_build_object('ok',false,'code','no_destination','requestId',r.id);end if;
 if b.proven_at<clock_timestamp()-interval '30 days'then
  update public.auth_code_requests set state='refused',refusal='reproof_required',webhook_id=p_webhook_id,body_hmac=p_body_hmac,updated_at=clock_timestamp()where id=r.id;
  return jsonb_build_object('ok',false,'code','reproof_required','requestId',r.id);end if;
 update public.auth_code_requests set state='sending',webhook_id=p_webhook_id,body_hmac=p_body_hmac,binding_id=b.id,binding_generation=b.generation,address=b.address,updated_at=clock_timestamp()where id=r.id;
 return jsonb_build_object('ok',true,'replay',false,'requestId',r.id,'address',b.address,'route','binding');
end$$;

-- Sender: arm the link attached to this outbox message with the token it just generated.
create function public.telegram_signin_link_arm(p_message uuid,p_token_hash text)returns jsonb
language plpgsql security definer set search_path=''as $$
declare l public.telegram_signin_links;
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 if coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$'then return jsonb_build_object('ok',false,'code','invalid');end if;
 select * into l from public.telegram_signin_links where message_id=p_message for update;
 if not found or l.state<>'pending'then return jsonb_build_object('ok',false,'code','none');end if;
 if not exists(select 1 from public.telegram_auth_bindings b where b.id=l.binding_id and b.active and b.generation=l.binding_generation)then
  update public.telegram_signin_links set state='cancelled'where id=l.id;return jsonb_build_object('ok',false,'code','none');end if;
 update public.telegram_signin_links set token_hash=p_token_hash,state='armed',armed_at=clock_timestamp(),expires_at=clock_timestamp()+interval '10 minutes'where id=l.id;
 perform public._telegram_auth_audit(l.auth_user_id,'signin_link.armed',jsonb_build_object('linkId',l.id,'step',l.step));
 return jsonb_build_object('ok',true,'step',l.step);
end$$;

-- Continue pressed: the link is still good, then one sign-in request for its member (route 'link').
create function public.telegram_signin_link_begin(p_token_hash text,p_nonce_hmac text)returns jsonb
language plpgsql security definer set search_path=''as $$
declare l public.telegram_signin_links;ph text;rid uuid;
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 if coalesce(p_token_hash,'')!~'^[a-f0-9]{64}$'or coalesce(p_nonce_hmac,'')!~'^[a-f0-9]{64}$'then return jsonb_build_object('ok',false,'code','expired');end if;
 select * into l from public.telegram_signin_links where token_hash=p_token_hash for update;
 if not found then return jsonb_build_object('ok',false,'code','expired');end if;
 -- A retry from the same browser may continue; anything else on a used link is "expired".
 if not(l.state='armed'or(l.state='redeeming'and l.redeem_nonce_hmac=p_nonce_hmac))or l.expires_at<=clock_timestamp()then
  if l.state in('armed','redeeming')and l.expires_at<=clock_timestamp()then update public.telegram_signin_links set state='expired'where id=l.id;end if;
  perform public._telegram_auth_audit(l.auth_user_id,'signin_link.refused',jsonb_build_object('linkId',l.id,'state',l.state));
  return jsonb_build_object('ok',false,'code','expired');end if;
 if not exists(select 1 from public.telegram_auth_bindings b where b.id=l.binding_id and b.active and b.generation=l.binding_generation and b.principal_ref=l.principal_ref)
  or exists(select 1 from public.workspace_staff where user_id=l.auth_user_id)or exists(select 1 from public.clinic_portal_memberships where user_id=l.auth_user_id)then
  update public.telegram_signin_links set state='cancelled'where id=l.id;
  perform public._telegram_auth_audit(l.auth_user_id,'signin_link.refused',jsonb_build_object('linkId',l.id,'reason','binding_or_role'));
  return jsonb_build_object('ok',false,'code','expired');end if;
 select phone into ph from auth.users where id=l.auth_user_id and phone_confirmed_at is not null and(banned_until is null or banned_until<=clock_timestamp());
 if ph is null then return jsonb_build_object('ok',false,'code','expired');end if;
 ph:='+'||ltrim(ph,'+');
 perform pg_advisory_xact_lock(hashtextextended('tg-auth-code:'||ph,0));
 if exists(select 1 from public.auth_code_requests where phone=ph and state in('issuing','sending')and lease_until>clock_timestamp())then
  return jsonb_build_object('ok',false,'code','busy');end if;
 update public.auth_code_requests set state='unknown',updated_at=clock_timestamp()where phone=ph and state in('issuing','sending');
 if l.request_id is not null then update public.auth_code_requests set state='cancelled',updated_at=clock_timestamp()where id=l.request_id and state not in('verified');end if;
 update public.auth_code_requests set code_sealed=null where code_sealed is not null and updated_at<clock_timestamp()-interval '2 minutes';
 insert into public.auth_code_requests(phone,nonce_hmac,lease_until,signin_link_id)values(ph,p_nonce_hmac,clock_timestamp()+interval '15 seconds',l.id)returning id into rid;
 update public.telegram_signin_links set state='redeeming',redeem_nonce_hmac=p_nonce_hmac,request_id=rid where id=l.id;
 return jsonb_build_object('ok',true,'requestId',rid,'phone',ph,'step',l.step);
end$$;

-- Hook (route 'link'): keep the sealed code on the request instead of sending it.
create function public.auth_code_request_seal(p_request uuid,p_webhook_id text,p_sealed text)returns jsonb
language plpgsql security definer set search_path=''as $$
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 update public.auth_code_requests set code_sealed=p_sealed,updated_at=clock_timestamp()
 where id=p_request and webhook_id=p_webhook_id and state='sending'and signin_link_id is not null and code_sealed is null;
 return jsonb_build_object('ok',true,'updated',found);
end$$;

-- Server, once: the sealed code for this browser's link request (then removed).
create function public.telegram_signin_link_code(p_request uuid,p_nonce_hmac text)returns jsonb
language plpgsql security definer set search_path=''as $$
declare r public.auth_code_requests;sealed text;
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 select * into r from public.auth_code_requests where id=p_request for update;
 if not found or r.nonce_hmac is distinct from p_nonce_hmac or r.signin_link_id is null or r.state<>'sent'or r.code_sealed is null
  or r.updated_at<clock_timestamp()-interval '2 minutes'
  or not exists(select 1 from public.telegram_signin_links l where l.id=r.signin_link_id and l.state='redeeming'and l.request_id=r.id and l.redeem_nonce_hmac=p_nonce_hmac and l.expires_at>clock_timestamp())then
  return jsonb_build_object('ok',false,'code','expired');end if;
 sealed:=r.code_sealed;
 update public.auth_code_requests set code_sealed=null where id=r.id;
 return jsonb_build_object('ok',true,'sealed',sealed,'phone',r.phone);
end$$;

-- After verifyOtp and auth_code_request_verified: the link is used.
create function public.telegram_signin_link_finish(p_request uuid,p_nonce_hmac text)returns jsonb
language plpgsql security definer set search_path=''as $$
declare l public.telegram_signin_links;
begin
 if auth.role()is distinct from 'service_role'then raise insufficient_privilege;end if;
 select l2.* into l from public.telegram_signin_links l2 join public.auth_code_requests r on r.id=l2.request_id
 where r.id=p_request and r.state='verified'and l2.redeem_nonce_hmac=p_nonce_hmac for update of l2;
 if not found then return jsonb_build_object('ok',false,'code','unknown');end if;
 if l.state='redeeming'then
  update public.telegram_signin_links set state='used',used_at=clock_timestamp()where id=l.id;
  perform public._telegram_auth_audit(l.auth_user_id,'signin_link.used',jsonb_build_object('linkId',l.id,'step',l.step));
 end if;
 return jsonb_build_object('ok',true,'step',l.step);
end$$;

revoke all on function public.telegram_signin_link_arm(uuid,text),public.telegram_signin_link_begin(text,text),public.auth_code_request_seal(uuid,text,text),
 public.telegram_signin_link_code(uuid,text),public.telegram_signin_link_finish(uuid,text)from public,anon,authenticated,service_role;
grant execute on function public.telegram_signin_link_arm(uuid,text),public.telegram_signin_link_begin(text,text),public.auth_code_request_seal(uuid,text,text),
 public.telegram_signin_link_code(uuid,text),public.telegram_signin_link_finish(uuid,text)to service_role;
